// Le rapport du matin porte sur les ventes de la veille : on calcule la date
// et le chemin du CSV attendu (produit par le générateur, spec 01), monté dans
// /data à la fois ici et côté service loader.
const dateVeille = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

return [
  {
    json: {
      date_veille: dateVeille,
      csv_path: `/data/export_${dateVeille}.csv`,
    },
  },
];

// Assemblage HTML minimal des 7 KPI (spec 03) ; mise en forme avancée
// (couleurs, flèches stylées, graphique bonus) réservée à la spec 05.
const row = $input.first().json;

const ca = row.ca_veille;
const j7 = row.comparaison_j7;
const mois = row.comparaison_moyenne_mois;
const topClients = row.top_clients || [];
const topProduits = row.top_produits || [];
const region = row.ca_region || [];
const alerte = row.alerte_chute;

const euros = (n) =>
  Number(n).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' \u20ac';

const fleche = (ecart) => (ecart >= 0 ? '\u25b2' : '\u25bc');

const lignes = (items, labelKey) =>
  items
    .map((i) => `<tr><td>${i[labelKey]}</td><td style="text-align:right">${euros(i.ca)}</td></tr>`)
    .join('');

const bandeauAlerte = alerte && alerte.alerte
  ? `<p><strong>Alerte : CA en forte baisse (${alerte.ecart_pourcent}% vs J-7)</strong></p>`
  : '';

const html = `
<html>
<body style="font-family: Arial, sans-serif; color:#222;">
${bandeauAlerte}
<h1>CA de la veille (${ca.date_veille}) : ${euros(ca.ca)}</h1>
<p>
  vs J-7 (${euros(j7.ca_j7)}) : ${fleche(j7.ecart_valeur)} ${j7.ecart_pourcent}%<br/>
  vs moyenne du mois (${euros(mois.ca_moyen_mois)}) : ${fleche(mois.ecart_valeur)} ${mois.ecart_pourcent}%
</p>
<h2>Top 5 clients</h2>
<table cellpadding="4">${lignes(topClients, 'cli_nom')}</table>
<h2>Top 5 produits</h2>
<table cellpadding="4">${lignes(topProduits, 'art_lib')}</table>
<h2>CA par région</h2>
<table cellpadding="4">${lignes(region, 'region')}</table>
</body>
</html>
`;

return [{ json: { subject: `Rapport commercial \u2014 ${ca.date_veille}`, html } }];

// Branche erreur (spec 04) : jamais de chiffres faux ou à zéro, juste la raison.
const row = $input.first().json;
const reason = row.reason || 'raison inconnue';

const html = `
<html>
<body style="font-family: Arial, sans-serif; color:#611a15;">
<h1>Rapport non g\u00e9n\u00e9r\u00e9</h1>
<p>Raison : ${reason}</p>
</body>
</html>
`;

return [{ json: { subject: 'ALERTE \u2014 Rapport non g\u00e9n\u00e9r\u00e9', html } }];
